@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SketchAuthoredStagePromotionTest {
 final Context context=RuntimeEnvironment.getApplication();
 interface Work{void run()throws Exception;}
 void worker(Work work)throws Exception{ExecutorService worker=Executors.newSingleThreadExecutor();try{worker.submit(()->{try{work.run();return null;}catch(Exception e){throw new RuntimeException(e);}}).get(120,TimeUnit.SECONDS);}finally{worker.shutdownNow();}}
 final class Fixture{
  final String id="stage_reuse_"+UUID.randomUUID();int serial;
  Fixture()throws Exception{
   File file=new File(context.getCacheDir(),id+".png");Bitmap guide=Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);try{guide.eraseColor(Color.RED);try(FileOutputStream out=new FileOutputStream(file)){assertTrue(guide.compress(Bitmap.CompressFormat.PNG,100,out));}}finally{guide.recycle();}ProjectStore projects=new ProjectStore(context);ProjectStore.Project project=projects.create("Hidden test guide");ProjectStore.Asset asset=projects.registerImportedAsset(project.id,Uri.fromFile(file),file.getName(),"image/png",0,file.length());
   SketchEditOps.execute(context,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","new").put("width",256).put("height",256).put("frameCount",2).put("background","#00000000"));SketchEditOps.execute(context,"sketch_import_reference",new JSONObject().put("sketchId",id).put("operationId","guide").put("expectedRevision",1).put("projectId",project.id).put("sourceProjectUpdatedAt",projects.get(project.id).updatedAt).put("assetId",asset.id).put("layerId","layer_1").put("objectId","guide").put("guideVisible",false));
   edit(SketchLayeredDrawingTest.begin());edit(SketchLayeredDrawingTest.stroke("actor_construction","construction"));review("construction");stage("refinement");JSONObject contour=SketchDocument.copy(SketchDocument.object(SketchContourPaintTest.fixture(),"authored_outline")).put("id","ink").put("exposure",2);
   edits(new JSONArray().put(new JSONObject().put("type","add_paint_cel").put("layerId","actor_refinement").put("objectId","paint").put("exposure",2)).put(new JSONObject().put("type","add_object").put("layerId","actor_refinement").put("object",contour)));
   JSONObject pins=SketchEditOps.execute(context,"sketch_inspect",new JSONObject().put("sketchId",id).put("expectedRevision",doc().getLong("revision")).put("contourObjectIds",new JSONArray().put("ink")));edit(new JSONObject().put("type","paint_fill").put("objectId","paint").put("strokeId","owned_fill").put("contourObjectId","ink").put("expectedContourSha256",pins.getJSONArray("contourPaintSources").getJSONObject(0).getString("contourSha256")).put("color","#806050A0"));
  }
  JSONObject doc()throws Exception{return SketchPaintMeshTest.load(context,id);}
  JSONObject request(JSONArray ops)throws Exception{return new JSONObject().put("sketchId",id).put("expectedRevision",doc().getLong("revision")).put("operationId","step_"+(serial++)).put("operations",ops);}
  JSONObject edits(JSONArray ops)throws Exception{return SketchEditOps.execute(context,"sketch_edit",request(ops));}
  void edit(JSONObject op)throws Exception{edits(new JSONArray().put(op));}
  void review(String stage)throws Exception{edit(new JSONObject().put("type","layered_drawing_review").put("stage",stage).put("reviewedRevision",doc().getLong("revision")).put("status","ACCEPTABLE").put("note","Inspected the native test marks."));}
  void stage(String stage)throws Exception{edit(new JSONObject().put("type","layered_drawing_stage").put("stage",stage));}
  void ready()throws Exception{review("refinement");stage("details");edit(SketchLayeredDrawingTest.stroke("actor_details","detail"));review("details");}
 }
 static JSONObject promotion()throws Exception{return new JSONObject().put("type","layered_drawing_stage").put("stage","clean_line").put("promote",new JSONArray().put(map("ink","clean_ink","head")).put(map("paint","clean_paint","head")).put(map("detail","clean_detail","body")));}
 static JSONObject map(String from,String to,String part)throws Exception{return new JSONObject().put("sourceObjectId",from).put("objectId",to).put("partId",part);}
 static JSONObject isolated(JSONObject document,String layer)throws Exception{JSONObject d=SketchDocument.copy(document);d.remove("layeredDrawing");JSONObject selected=SketchDocument.copy(SketchDocument.layer(d,layer)).put("visible",true).put("locked",false);return d.put("layers",new JSONArray().put(selected));}
 void exact(JSONObject before,String source,JSONObject after,String target)throws Exception{try(SketchFrameRenderer a=new SketchFrameRenderer(context,isolated(before,source));SketchFrameRenderer b=new SketchFrameRenderer(context,isolated(after,target))){for(int f=0;f<2;f++){Bitmap x=a.render(f,false),y=b.render(f,false);try{int[] p=new int[256*256],q=new int[p.length];x.getPixels(p,0,256,0,0,256,256);y.getPixels(q,0,256,0,0,256,256);assertArrayEquals("Owned stage reuse preserves every native RGBA value",p,q);}finally{x.recycle();y.recycle();}}}}
 @Test public void publicReuseKeepsExactPaintPixelsSourceReviewsUndoArchiveAndStrokeIdentity()throws Exception{worker(()->{
  Fixture f=new Fixture();JSONObject transform=new JSONObject().put("rotation",17).put("scaleX",.9).put("scaleY",1.05).put("anchorX",.47).put("anchorY",.61).put("opacity",.73);f.edits(new JSONArray().put(new JSONObject().put("type","set_transform").put("objectId","paint").put("transform",transform)).put(new JSONObject().put("type","set_transform").put("objectId","ink").put("transform",transform)));f.ready();JSONObject before=f.doc();String sourceHash=SketchLayeredDrawing.stageContentSha256(before,"refinement"),paintHash=SketchDocument.object(before,"paint").getJSONObject("paint").getString("sha256"),guide=SketchDocument.canonical(SketchDocument.layer(before,"layer_1"));
  JSONObject request=f.request(new JSONArray().put(promotion())),receipt=SketchEditOps.execute(context,"sketch_edit",request),after=f.doc();assertEquals(SketchDocument.canonical(receipt),SketchDocument.canonical(SketchEditOps.execute(context,"sketch_edit",request)));assertEquals(sourceHash,SketchLayeredDrawing.stageContentSha256(after,"refinement"));assertEquals(guide,SketchDocument.canonical(SketchDocument.layer(after,"layer_1")));assertEquals(paintHash,SketchDocument.object(after,"clean_paint").getJSONObject("paint").getString("sha256"));assertTrue(SketchLayeredDrawing.currentReviewAccepted(after,"refinement"));exact(before,"actor_refinement",after,"actor_head");
  JSONObject reusedStroke=new JSONObject().put("type","paint_stroke").put("objectId","clean_paint").put("strokeId","owned_fill").put("points",new JSONArray("[[.5,.5,1]]")).put("brush",new JSONObject().put("mode","paint").put("color","#FF000000").put("sizePx",8));assertThrows(IllegalStateException.class,()->f.edit(reusedStroke));assertEquals(after.getLong("revision"),f.doc().getLong("revision"));
  SketchPaintArchive.Prepared archive=SketchPaintArchive.prepare(context,new JSONObject().put("sketchId",f.id).put("expectedRevision",after.getLong("revision")).put("operationId","archive"));JSONObject restored=SketchPaintArchive.restoreFile(context,archive.file,SketchProjectStore.fileHash(archive.file),"restored_"+UUID.randomUUID(),"Reused owned parts");exact(before,"actor_refinement",SketchPaintMeshTest.load(context,restored.getString("sketchId")),"actor_head");
  SketchEditOps.execute(context,"sketch_undo",new JSONObject().put("sketchId",f.id).put("expectedRevision",f.doc().getLong("revision")).put("operationId","undo"));assertEquals("details",f.doc().getJSONObject("layeredDrawing").getString("stage"));assertEquals(0,SketchDocument.layer(f.doc(),"actor_head").getJSONArray("objects").length());assertEquals(sourceHash,SketchLayeredDrawing.stageContentSha256(f.doc(),"refinement"));SketchEditOps.execute(context,"sketch_redo",new JSONObject().put("sketchId",f.id).put("expectedRevision",f.doc().getLong("revision")).put("operationId","redo"));exact(before,"actor_refinement",f.doc(),"actor_head");
 });}
 @Test public void rejectsForeignReferenceStaleReviewDuplicateIdsAndDifferentLayerCoordinatesAtomically()throws Exception{worker(()->{
  Fixture f=new Fixture();f.ready();JSONObject valid=promotion(),before=f.doc();String unchanged=SketchDocument.canonical(before);
  for(String source:new String[]{"guide","construction","absent"}){JSONObject bad=SketchDocument.copy(valid);bad.getJSONArray("promote").getJSONObject(0).put("sourceObjectId",source);assertThrows(IllegalArgumentException.class,()->f.edit(bad));assertEquals(unchanged,SketchDocument.canonical(f.doc()));}
  JSONObject duplicate=SketchDocument.copy(valid);duplicate.getJSONArray("promote").getJSONObject(1).put("objectId","clean_ink");assertThrows(IllegalArgumentException.class,()->f.edit(duplicate));JSONObject wrong=SketchDocument.copy(valid);wrong.getJSONArray("promote").getJSONObject(0).put("partId","unknown");assertThrows(IllegalArgumentException.class,()->f.edit(wrong));
  JSONObject different=SketchDocument.copy(before);SketchDocument.layer(different,"actor_head").getJSONObject("transform").put("rotation",15);assertThrows(IllegalArgumentException.class,()->SketchAuthoredStagePromotion.sources(different,valid));JSONObject locked=SketchDocument.copy(before);SketchDocument.layer(locked,"actor_refinement").put("locked",true);assertThrows(IllegalStateException.class,()->SketchAuthoredStagePromotion.sources(locked,valid));
  JSONObject stale=f.request(new JSONArray().put(valid));f.stage("refinement");f.edit(new JSONObject().put("type","update_object").put("objectId","ink").put("patch",new JSONObject().put("width",.01)));assertThrows(IllegalStateException.class,()->SketchEditOps.execute(context,"sketch_edit",stale));assertThrows(IllegalStateException.class,()->f.stage("details"));assertThrows(IllegalArgumentException.class,()->SketchAuthoredStagePromotion.sources(f.doc(),valid));
 });}
 @Test public void nativePaintAncestryRejectsEmptyCloneDerivedAndCancelledSources()throws Exception{worker(()->{
  Fixture f=new Fixture();try(SketchPaintStore assets=new SketchPaintStore(context,f.id)){JSONObject empty=assets.empty(256,256);assertThrows(IllegalArgumentException.class,()->assets.requireAuthoredStageSource(empty));JSONObject original=SketchDocument.object(f.doc(),"paint").getJSONObject("paint");assets.requireAuthoredStageSource(original);JSONObject detached=f.doc();detached.remove("layeredDrawing");JSONObject clone=new JSONObject().put("type","paint_stroke").put("objectId","paint").put("strokeId","cloned_source").put("points",new JSONArray("[[.5,.5,1]]")).put("brush",new JSONObject().put("mode","clone").put("color","#FFFFFFFF").put("sizePx",32)).put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",SketchDocument.object(detached,"guide").getJSONObject("reference").getString("sha256")));SketchPaintStore.PreparedChange copied=assets.prepare(detached,clone);assertThrows(IllegalArgumentException.class,()->assets.requireAuthoredStageSource(copied.descriptor));Thread.currentThread().interrupt();try{assertThrows(InterruptedException.class,()->assets.requireAuthoredStageSource(original));}finally{Thread.interrupted();}}
 });}
 @Test public void generatedIdsAndReceiptsPreventDuplicatesAndCancellationCanRetryTheSameIntent()throws Exception{worker(()->{
  Fixture f=new Fixture();f.ready();JSONObject promote=new JSONObject().put("type","layered_drawing_stage").put("stage","clean_line").put("promote",new JSONArray().put(new JSONObject().put("sourceObjectId","paint").put("partId","head")).put(new JSONObject().put("sourceObjectId","ink").put("partId","head")));JSONObject request=f.request(new JSONArray().put(promote)),receipt=SketchEditOps.execute(context,"sketch_edit",request);JSONArray pins=receipt.getJSONArray("authoredStagePromotions");assertEquals(2,pins.length());String target=pins.getJSONObject(0).getString("objectId");assertTrue(target.matches("clean_head_paint_[a-f0-9]{16}"));assertEquals(SketchDocument.object(f.doc(),"paint").getJSONObject("paint").getString("sha256"),pins.getJSONObject(0).getString("sourcePaintSha256"));assertEquals(SketchDocument.canonical(receipt),SketchDocument.canonical(SketchEditOps.execute(context,"sketch_edit",request)));String before=SketchDocument.canonical(f.doc());assertThrows(IllegalArgumentException.class,()->f.edit(promote));assertEquals(before,SketchDocument.canonical(f.doc()));
  JSONObject body=new JSONObject().put("type","layered_drawing_stage").put("stage","clean_line").put("promote",new JSONArray().put(new JSONObject().put("sourceObjectId","ink").put("partId","body"))),retry=f.request(new JSONArray().put(body));Thread.currentThread().interrupt();try{assertThrows(java.io.InterruptedIOException.class,()->SketchEditOps.execute(context,"sketch_edit",retry));}finally{Thread.interrupted();}assertEquals(before,SketchDocument.canonical(f.doc()));JSONObject recovered=SketchEditOps.execute(context,"sketch_edit",retry);assertEquals(1,recovered.getJSONArray("authoredStagePromotions").length());assertEquals(1,SketchDocument.layer(f.doc(),"actor_body").getJSONArray("objects").length());
 });}

}
